// Generated by AutoDeploy. The native shell around the website: a full-screen WebView plus the
// `window.NativeApp` bridge, so the site can use native features (share sheet, haptics, push
// notifications, Face ID / fingerprint) when it runs inside the app.
// Settings live in autodeploy.config.json; change them in the panel and rebuild.
import React, { useCallback, useEffect, useRef, useState } from 'react'
import { ActivityIndicator, BackHandler, Linking, Platform, Pressable, Share, StyleSheet, Text, View } from 'react-native'
import { WebView } from 'react-native-webview'
import { SafeAreaProvider, useSafeAreaInsets } from 'react-native-safe-area-context'
import { StatusBar } from 'expo-status-bar'
import * as SplashScreen from 'expo-splash-screen'
import * as WebBrowser from 'expo-web-browser'
// @feature haptics
import * as Haptics from 'expo-haptics'
// @end
// @feature push
import * as Notifications from 'expo-notifications'
// @end
// @feature biometrics
import * as LocalAuthentication from 'expo-local-authentication'
// @end
import config from './autodeploy.config.json'

SplashScreen.preventAutoHideAsync().catch(() => {})

const hostOf = (url) => {
  const m = /^[a-z][a-z0-9+.-]*:\/\/(?:[^@/?#]*@)?([^/?#:]+)/i.exec(url || '')
  return m ? m[1].toLowerCase() : ''
}
// The site's own domain and its subdomains, plus the extra hosts set in the panel (payment pages, sign-in)
const isAppHost = (host) => !!host && (host === config.domain || host.endsWith('.' + config.domain) || config.hosts.includes(host))

/** A deep link (https://<domain>/… or <scheme>://…) as a page of the site, or null. */
function toSiteUrl(link) {
  if (!link) return null
  if (/^https?:/i.test(link)) return isAppHost(hostOf(link)) ? link : null
  const m = /^[a-z][a-z0-9+.-]*:\/\/\/?(.*)$/i.exec(link)
  return m ? `${config.origin}/${m[1].replace(/^\/+/, '')}` : null
}

const BRIDGE_INFO = {
  isNative: true,
  platform: Platform.OS,
  appVersion: config.version,
  build: config.buildNumber,
  features: config.bridgeFeatures
}

// Runs in the page before its own scripts. Each call returns a Promise answered by onMessage below.
const BRIDGE = `(function () {
  if (window.NativeApp) return;
  var seq = 0, pending = {};
  function call(method, args) {
    return new Promise(function (resolve, reject) {
      var id = ++seq;
      pending[id] = [resolve, reject];
      window.ReactNativeWebView.postMessage(JSON.stringify({ autodeploy: 1, id: id, method: method, args: args || {} }));
    });
  }
  window.__nativeAppReply = function (id, ok, value) {
    var p = pending[id];
    if (!p) return;
    delete pending[id];
    if (ok) p[0](value); else p[1](new Error(value));
  };
  var api = ${JSON.stringify(BRIDGE_INFO)};
  api.has = function (feature) { return api.features.indexOf(feature) !== -1; };
  api.share = function (o) { return call('share', o); };
  api.haptic = function (type) { return call('haptic', { type: type || 'light' }); };
  api.getPushToken = function () { return call('pushToken'); };
  api.authenticate = function (reason) { return call('authenticate', { reason: reason }); };
  api.openExternal = function (url) { return call('openExternal', { url: url }); };
  window.NativeApp = api;
  var ready = function () { document.dispatchEvent(new Event('nativeappready')); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ready); else ready();
})(); true;`

// @feature push
Notifications.setNotificationHandler({
  handleNotification: async () => ({ shouldShowAlert: true, shouldShowBanner: true, shouldShowList: true, shouldPlaySound: true, shouldSetBadge: false })
})

async function getPushToken() {
  if (Platform.OS === 'android') {
    await Notifications.setNotificationChannelAsync('default', { name: 'Notifications', importance: Notifications.AndroidImportance.HIGH })
  }
  let { status } = await Notifications.getPermissionsAsync()
  if (status !== 'granted') status = (await Notifications.requestPermissionsAsync()).status
  if (status !== 'granted') throw new Error('Notification permission was not granted')
  const token = await Notifications.getDevicePushTokenAsync()
  return { token: token.data, type: token.type, platform: Platform.OS }
}
// @end

// @feature haptics
const IMPACT = { light: 'Light', medium: 'Medium', heavy: 'Heavy', soft: 'Soft', rigid: 'Rigid' }
const NOTIFY = { success: 'Success', warning: 'Warning', error: 'Error' }
// @end

/** Native methods the page may call through window.NativeApp. */
const HANDLERS = {
  async share({ title, text, url }) {
    const content = Platform.OS === 'ios' ? { title, message: text, url } : { title, message: [text, url].filter(Boolean).join('\n') }
    const result = await Share.share(content)
    return result.action === Share.sharedAction
  },
  async openExternal({ url }) {
    if (!/^(https?|mailto|tel|sms):/i.test(String(url || ''))) throw new Error('Only http(s), mailto, tel and sms links can be opened')
    await Linking.openURL(url)
    return true
  },
  // @feature haptics
  async haptic({ type }) {
    if (type === 'selection') await Haptics.selectionAsync()
    else if (NOTIFY[type]) await Haptics.notificationAsync(Haptics.NotificationFeedbackType[NOTIFY[type]])
    else await Haptics.impactAsync(Haptics.ImpactFeedbackStyle[IMPACT[type] || 'Light'])
    return true
  },
  // @end
  // @feature push
  pushToken: getPushToken,
  // @end
  // @feature biometrics
  async authenticate({ reason }) {
    if (!(await LocalAuthentication.hasHardwareAsync())) return { success: false, error: 'not_available' }
    if (!(await LocalAuthentication.isEnrolledAsync())) return { success: false, error: 'not_enrolled' }
    const r = await LocalAuthentication.authenticateAsync({ promptMessage: reason || `Unlock ${config.name}` })
    return r.success ? { success: true } : { success: false, error: r.error }
  },
  // @end
}

function Main() {
  const insets = useSafeAreaInsets()
  const webRef = useRef(null)
  const canGoBack = useRef(false)
  const loaded = useRef(false)
  const [progress, setProgress] = useState(0)
  const [error, setError] = useState(null)

  const open = useCallback((url) => {
    if (!url) return
    if (loaded.current && webRef.current) webRef.current.injectJavaScript(`window.location.href = ${JSON.stringify(url)}; true;`)
    else setTimeout(() => open(url), 500)
  }, [])

  // Android back button walks back through the site before leaving the app
  useEffect(() => {
    if (Platform.OS !== 'android') return undefined
    const sub = BackHandler.addEventListener('hardwareBackPress', () => {
      if (!canGoBack.current) return false
      webRef.current?.goBack()
      return true
    })
    return () => sub.remove()
  }, [])

  // Links into the site (https://<domain>/… or <scheme>://…) open that page
  useEffect(() => {
    Linking.getInitialURL().then((link) => open(toSiteUrl(link))).catch(() => {})
    const sub = Linking.addEventListener('url', ({ url }) => open(toSiteUrl(url)))
    return () => sub.remove()
  }, [open])

  // @feature push
  // Tapping a notification whose data has { url } opens that page
  useEffect(() => {
    const go = (response) => open(toSiteUrl(response?.notification?.request?.content?.data?.url))
    Notifications.getLastNotificationResponseAsync().then(go).catch(() => {})
    const sub = Notifications.addNotificationResponseReceivedListener(go)
    return () => sub.remove()
  }, [open])
  // @end

  // Never keep the splash screen up for long, even if the first page is slow
  useEffect(() => {
    const t = setTimeout(() => SplashScreen.hideAsync().catch(() => {}), 8000)
    return () => clearTimeout(t)
  }, [])

  const onShouldStart = useCallback((req) => {
    const url = req.url || ''
    if (req.isTopFrame === false) return true // iframes: videos, maps, payment widgets
    if (/^(about:|data:|blob:|javascript:)/i.test(url)) return true
    if (/^https?:/i.test(url)) {
      if (isAppHost(hostOf(url)) || !config.externalLinks) return true
      WebBrowser.openBrowserAsync(url).catch(() => Linking.openURL(url).catch(() => {}))
      return false
    }
    // tel:, mailto:, sms:, whatsapp:, upi:, store links…
    Linking.openURL(url).catch(() => {})
    return false
  }, [])

  const onMessage = useCallback(async (event) => {
    let msg
    try { msg = JSON.parse(event.nativeEvent.data) } catch { return }
    if (!msg || msg.autodeploy !== 1) return
    const reply = (ok, value) => webRef.current?.injectJavaScript(`window.__nativeAppReply(${Number(msg.id)}, ${ok}, ${JSON.stringify(value ?? null)}); true;`)
    // Only the app's own pages may use native features
    if (!isAppHost(hostOf(event.nativeEvent.url))) return reply(false, 'Native features are not available on this page')
    const handler = HANDLERS[msg.method]
    if (!handler) return reply(false, `${msg.method} is not enabled in this app`)
    try {
      reply(true, await handler(msg.args || {}))
    } catch (err) {
      reply(false, String(err?.message || err))
    }
  }, [])

  const retry = () => {
    setError(null)
    webRef.current?.reload()
  }

  return (
    <View style={[styles.root, { backgroundColor: config.backgroundColor }]}>
      <StatusBar style={config.statusBarStyle} />
      <View style={{ height: insets.top, backgroundColor: config.themeColor }} />
      <View style={{ flex: 1, paddingBottom: insets.bottom, paddingLeft: insets.left, paddingRight: insets.right }}>
        <WebView
          ref={webRef}
          source={{ uri: config.startUrl }}
          originWhitelist={['*']}
          injectedJavaScriptBeforeContentLoaded={BRIDGE}
          onMessage={onMessage}
          onShouldStartLoadWithRequest={onShouldStart}
          onNavigationStateChange={(s) => { canGoBack.current = s.canGoBack }}
          onLoadProgress={({ nativeEvent }) => setProgress(nativeEvent.progress)}
          onLoadEnd={() => {
            loaded.current = true
            SplashScreen.hideAsync().catch(() => {})
          }}
          onError={({ nativeEvent }) => setError(nativeEvent.description || 'The page could not be loaded.')}
          onFileDownload={({ nativeEvent }) => Linking.openURL(nativeEvent.downloadUrl).catch(() => {})}
          onContentProcessDidTerminate={() => webRef.current?.reload()}
          onRenderProcessGone={() => webRef.current?.reload()}
          applicationNameForUserAgent={`AutoDeployApp/${config.version}`}
          javaScriptEnabled
          domStorageEnabled
          sharedCookiesEnabled
          thirdPartyCookiesEnabled
          allowsBackForwardNavigationGestures
          allowsInlineMediaPlayback
          mediaPlaybackRequiresUserAction={false}
          setSupportMultipleWindows={false}
          pullToRefreshEnabled={config.pullToRefresh}
          geolocationEnabled={config.location}
          mediaCapturePermissionGrantType={config.camera ? 'grantIfSameHostElsePrompt' : 'deny'}
          style={{ backgroundColor: config.backgroundColor }}
        />
        {progress > 0 && progress < 1 && <View style={[styles.progress, { width: `${progress * 100}%`, backgroundColor: config.themeColor }]} />}
        {error && (
          <View style={[styles.overlay, { backgroundColor: config.backgroundColor }]}>
            <Text style={styles.title}>{config.name}</Text>
            <Text style={styles.message}>{config.offlineMessage}</Text>
            <Pressable onPress={retry} style={[styles.button, { backgroundColor: config.themeColor }]}>
              <Text style={styles.buttonText}>Try again</Text>
            </Pressable>
          </View>
        )}
        {!error && progress === 0 && <ActivityIndicator style={styles.spinner} color={config.themeColor} />}
      </View>
    </View>
  )
}

export default function App() {
  return (
    <SafeAreaProvider>
      <Main />
    </SafeAreaProvider>
  )
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  progress: { position: 'absolute', top: 0, left: 0, height: 2 },
  spinner: { position: 'absolute', top: '50%', alignSelf: 'center' },
  overlay: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', padding: 32 },
  title: { fontSize: 20, fontWeight: '700', color: '#111', marginBottom: 8 },
  message: { fontSize: 15, color: '#555', textAlign: 'center', marginBottom: 24 },
  button: { paddingHorizontal: 24, paddingVertical: 12, borderRadius: 999 },
  buttonText: { color: '#fff', fontWeight: '600', fontSize: 15 }
})
